{
  "states": [
    "LISTEN",
    "REQUEST",
    "RESPOND",
    "PARTOPEN",
    "OPEN",
    "CLOSEREQ",
    "CLOSING",
    "TIMEWAIT",
    "CLOSED"
  ],
  "transitions": [
    {
      "from": "LISTEN",
      "event": "rcv Request",
      "action": "snd Response",
      "to": "RESPOND"
    },
    {
      "from": "RESPOND",
      "event": "rcv Ack/DataAck",
      "action": "leaves the RESPOND state for OPEN",
      "to": "OPEN"
    },
    {
      "from": "RESPOND",
      "event": "timeout of not less than 4MSL",
      "action": "send a DCCP-Reset with Reset Code 2, 'Aborted'",
      "to": "CLOSED"
    },
    {
      "from": "REQUEST",
      "event": "rcv Response",
      "action": "moves from the REQUEST state to PARTOPEN",
      "to": "PARTOPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "rcv packet other than DCCP-Response, DCCP-Reset, or DCCP-Sync",
      "action": "leaves the PARTOPEN state for OPEN",
      "to": "OPEN"
    },
    {
      "from": "OPEN",
      "event": "snd CloseReq",
      "action": "server active close",
      "to": "CLOSEREQ"
    },
    {
      "from": "OPEN",
      "event": "active close or rcv CloseReq",
      "action": "client moves from OPEN through CLOSING",
      "to": "CLOSING"
    },
    {
      "from": "CLOSEREQ",
      "event": "rcv Close",
      "action": "snd Reset",
      "to": "CLOSED"
    },
    {
      "from": "CLOSING",
      "event": "rcv Reset",
      "action": "hold TIMEWAIT state",
      "to": "TIMEWAIT"
    },
    {
      "from": "TIMEWAIT",
      "event": "2MSL timer expires",
      "action": "transition to CLOSED",
      "to": "CLOSED"
    },
    {
      "from": "LISTEN",
      "event": "rcv Reset",
      "action": "hold TIMEWAIT state",
      "to": "TIMEWAIT"
    },
    {
      "from": "REQUEST",
      "event": "rcv Reset",
      "action": "hold TIMEWAIT state",
      "to": "TIMEWAIT"
    },
    {
      "from": "RESPOND",
      "event": "rcv Reset",
      "action": "hold TIMEWAIT state",
      "to": "TIMEWAIT"
    },
    {
      "from": "PARTOPEN",
      "event": "rcv Reset",
      "action": "hold TIMEWAIT state",
      "to": "TIMEWAIT"
    },
    {
      "from": "OPEN",
      "event": "rcv Reset",
      "action": "hold TIMEWAIT state",
      "to": "TIMEWAIT"
    },
    {
      "from": "CLOSEREQ",
      "event": "rcv Reset",
      "action": "hold TIMEWAIT state",
      "to": "TIMEWAIT"
    }
  ]
}

